import os
import json
from google.cloud import documentai_v1 as documentai

def extract_key_values(payload, config=None):
    config = config or {}
    project_id = config.get("project_id") or os.environ.get("GOOGLE_CLOUD_PROJECT")
    location = config.get("location") or "us"
    processor_id = config.get("processor_id")
    mime_type = config.get("mime_type") or "application/pdf"

    if not project_id or not processor_id:
        raise ValueError("project_id and processor_id are required")

    client = documentai.DocumentProcessorServiceClient()
    name = client.processor_path(project_id, location, processor_id)

    if isinstance(payload, str):
        if payload.startswith("http://") or payload.startswith("https://"):
            raw_document = documentai.RawDocument(
                content=payload.encode("utf-8"),
                mime_type=mime_type,
            )
        else:
            with open(payload, "rb") as f:
                raw_document = documentai.RawDocument(
                    content=f.read(),
                    mime_type=mime_type,
                )
    elif isinstance(payload, (bytes, bytearray)):
        raw_document = documentai.RawDocument(
            content=bytes(payload),
            mime_type=mime_type,
        )
    else:
        raw_document = documentai.RawDocument(
            content=json.dumps(payload).encode("utf-8"),
            mime_type=mime_type,
        )

    request = documentai.ProcessRequest(
        name=name,
        raw_document=raw_document,
    )
    response = client.process_document(request=request)
    doc = response.document

    result = {}
    for entity in doc.entities:
        key = entity.type_ or "unknown"
        value = entity.mention_text or ""
        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value

    for page in doc.pages:
        for form_field in page.form_fields:
            key = form_field.field_name.text_anchor.content if form_field.field_name and form_field.field_name.text_anchor else form_field.field_name.text if form_field.field_name else ""
            value = form_field.field_value.text_anchor.content if form_field.field_value and form_field.field_value.text_anchor else form_field.field_value.text if form_field.field_value else ""
            key = (key or "").strip()
            value = (value or "").strip()
            if key:
                result[key] = value

    return result
